<style>
.bs-about-contact{padding:82px 4%;background:#f7f8fc}.bs-about-wrap{max-width:1320px;margin:auto}.about-grid,.contact-grid{display:grid;grid-template-columns:1.08fr .92fr;gap:28px;align-items:stretch}.about-card,.contact-card{background:#fff;border:1px solid #e7eaf0;border-radius:24px;box-shadow:0 16px 40px rgba(19,29,49,.06);overflow:hidden}.about-copy{padding:42px}.section-eyebrow{font-size:11px;letter-spacing:.14em;text-transform:uppercase;font-weight:800;color:#6a5ce3}.about-copy h2,.contact-copy h2{font-size:36px;line-height:1.1;color:#172033;margin:10px 0 16px}.about-copy p,.contact-copy p{font-size:14px;line-height:1.8;color:#667085}.about-features{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:25px}.about-feature{padding:15px;border:1px solid #eef0f4;border-radius:14px;background:#fafbff}.about-feature i{color:#6a5ce3;font-size:17px}.about-feature strong{display:block;margin-top:7px;font-size:12px;color:#243046}.about-feature span{display:block;margin-top:3px;font-size:11px;color:#7b8492;line-height:1.5}.about-image img{width:100%;height:100%;min-height:360px;object-fit:cover;display:block}.contact-grid{margin-top:28px;grid-template-columns:.85fr 1.15fr}.contact-copy{padding:42px}.contact-info-list{display:grid;gap:14px;margin-top:24px}.contact-info-item{display:flex;gap:12px;align-items:center}.contact-icon{width:42px;height:42px;border-radius:12px;display:grid;place-items:center;background:#f0efff;color:#6a5ce3}.contact-info-item strong{display:block;font-size:12px;color:#243046}.contact-info-item span{display:block;font-size:12px;color:#7b8492;margin-top:2px}.contact-form{padding:30px;background:#fbfbfd}.contact-form h3{margin:0 0 18px;font-size:19px;color:#172033}.form-row{display:grid;grid-template-columns:1fr 1fr;gap:12px}.bs-input,.bs-textarea{width:100%;box-sizing:border-box;border:1px solid #e3e7ee;background:#fff;border-radius:12px;padding:12px 13px;font-size:13px;outline:none;transition:.2s}.bs-input:focus,.bs-textarea:focus{border-color:#bdb5ff;box-shadow:0 0 0 4px rgba(106,92,227,.08)}.bs-textarea{min-height:130px;resize:vertical;margin-top:12px}.send-btn{margin-top:12px;border:0;background:linear-gradient(135deg,#5b4bdb,#7867ea);color:#fff;border-radius:12px;padding:12px 18px;font-weight:750;cursor:pointer}.send-btn:hover{filter:brightness(.97)}.contact-message{display:none;margin-bottom:12px;padding:11px 12px;border-radius:10px;font-size:12px}.contact-message.show{display:block}.contact-message.success{background:#ecfdf3;color:#16704a}.contact-message.error{background:#fff1f2;color:#b4233f}@media(max-width:900px){.about-grid,.contact-grid{grid-template-columns:1fr}.about-image{order:-1}.about-image img{min-height:260px}.about-features{grid-template-columns:1fr}.form-row{grid-template-columns:1fr}}
</style>
<section class="bs-about-contact" id="about-contact"><div class="bs-about-wrap">
<div class="about-grid"><div class="about-card about-copy"><div class="section-eyebrow">About BookSpot</div><h2>A better home for curious readers.</h2><p>BookSpot brings together physical books, rentals and digital reading in one simple place. We focus on useful recommendations, easy discovery and a smoother way to keep reading.</p><div class="about-features"><div class="about-feature"><i class="fa-solid fa-book-open"></i><strong>Curated books</strong><span>Thoughtfully selected titles across popular genres.</span></div><div class="about-feature"><i class="fa-solid fa-bolt"></i><strong>Quick discovery</strong><span>Search, browse and move to your next read faster.</span></div><div class="about-feature"><i class="fa-solid fa-heart"></i><strong>Reader first</strong><span>A clean experience designed around book lovers.</span></div></div></div><div class="about-card about-image"><img src="<?= base_url('assets/uploads/360_F_619598670_r3J7JKkXw4xy7CMN6RLdAOZrcXXautfk.jpg'); ?>" alt="BookSpot reading collection"></div></div>
<div class="contact-grid" id="contact"><div class="contact-card contact-copy"><div class="section-eyebrow">Need help?</div><h2>Let’s talk about books.</h2><p>Questions about an order, rental, eBook or recommendation? Send us a note and the BookSpot team will get back to you.</p><div class="contact-info-list"><div class="contact-info-item"><div class="contact-icon"><i class="fa-solid fa-phone"></i></div><div><strong>Phone</strong><span>83696 15205</span></div></div><div class="contact-info-item"><div class="contact-icon"><i class="fa-solid fa-envelope"></i></div><div><strong>Email</strong><span>cs@bookspot.com</span></div></div><div class="contact-info-item"><div class="contact-icon"><i class="fa-solid fa-location-dot"></i></div><div><strong>Location</strong><span>Mumbai, Maharashtra</span></div></div></div></div><div class="contact-card contact-form"><h3>Send a message</h3><div id="contactMessage" class="contact-message"></div><form id="bookContactForm"><div class="form-row"><input class="bs-input" type="text" name="name" placeholder="Your name" required><input class="bs-input" type="email" name="email" placeholder="Your email" required></div><textarea class="bs-textarea" name="message" placeholder="How can we help?" required></textarea><button class="send-btn" type="submit"><i class="fa-regular fa-paper-plane"></i> Send Message</button></form></div></div></div></section>
<script>document.addEventListener('DOMContentLoaded',function(){const f=document.getElementById('bookContactForm'),m=document.getElementById('contactMessage');if(!f)return;f.addEventListener('submit',async function(e){e.preventDefault();m.className='contact-message';m.textContent='Sending...';m.classList.add('show');try{const r=await fetch('<?= site_url('contact/send'); ?>',{method:'POST',headers:{'X-Requested-With':'XMLHttpRequest','Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(new FormData(f))});const d=await r.json();m.textContent=d.message||'Done';m.classList.add(d.status==='success'?'success':'error');if(d.status==='success')f.reset();}catch(err){m.textContent='Could not send your message right now.';m.classList.add('error');}});});</script>
